"""Build the public CBR information pages without changing Kodi's source index."""
from pathlib import Path
import html
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'website'
SOURCE = 'https://anakra1.github.io/androitdtvfire/'
BASE = SOURCE + 'website/'
versions = {platform: ET.parse(ROOT / platform / 'addons.xml').getroot().find(
    "addon[@id='plugin.video.stremio.bridge']").get('version') for platform in ('windows', 'android')}

ICONS = {
    'arrow': '<path d="M5 12h14m-6-6 6 6-6 6"/>',
    'download': '<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>',
    'windows': '<path d="m3 5 7-1v7H3zm10-1 8-1v8h-8zM3 14h7v7l-7-1zm10 0h8v9l-8-1z"/>',
    'tv': '<rect x="3" y="6" width="18" height="13" rx="2"/><path d="m8 2 4 4 4-4m-7 17v3m6-3v3M8 22h8"/>',
    'guide': '<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M3 10h18M9 10v11M15 10v11M8 2v4m8-4v4"/>',
    'source': '<path d="M9 15l6-6m-7 3-2 2a4 4 0 0 0 6 6l2-2m-4-12 2-2a4 4 0 0 1 6 6l-2 2"/>',
    'play': '<path d="m8 4 13 8-13 8z"/>',
}


def icon(name):
    return '<svg viewBox="0 0 24 24" aria-hidden="true">' + ICONS[name] + '</svg>'


def source_panel(identity='source-url'):
    return f'''<div class="source-panel"><div class="source-heading">{icon('source')}<div><h3>One source address. Both platforms.</h3><p>Add this in Kodi File manager and name it <strong>CBR</strong>.</p></div></div>
    <div class="copy-row"><input id="{identity}" aria-label="Kodi source URL" readonly value="{SOURCE}" spellcheck="false"><button class="button" type="button" data-copy="{identity}" data-status="{identity}-status">Copy source URL</button></div>
    <p class="copy-status" id="{identity}-status" role="status" aria-live="polite"></p><p class="source-note">The website explains the setup. The source address above is the one to enter in Kodi.</p></div>'''


def page_hero(label, title, description, pills=''):
    return f'''<section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span>{label}</span></div><p class="eyebrow kicker">Crimson Blood Requiem</p><h1>{title}</h1><p class="lead">{description}</p>{pills}</div></section>'''


def render(filename, title, description, content):
    navigation = [('index.html', 'Home'), ('android.html', 'Android / Fire TV'), ('windows.html', 'Windows'), ('help.html', 'Help & updates')]
    nav = ''.join(f'<a href="{path}"' + (' aria-current="page"' if path == filename else '') + f'>{label}</a>' for path, label in navigation)
    brand = '<span class="brand-mark">CBR</span><span class="brand-name">Crimson Blood<br>Requiem</span>'
    output = f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)} | Crimson Blood Requiem</title><meta name="description" content="{html.escape(description, quote=True)}">
<meta name="theme-color" content="#10090e"><link rel="canonical" href="{BASE + ('' if filename == 'index.html' else filename)}">
<meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title, quote=True)} | CBR"><meta property="og:description" content="{html.escape(description, quote=True)}"><meta property="og:image" content="{BASE}assets/crimson-fleet.jpg"><meta property="og:url" content="{BASE + ('' if filename == 'index.html' else filename)}">
<link rel="icon" type="image/png" href="assets/cbr-icon.png"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Crimson Blood Requiem home">{brand}</a><nav class="main-nav" aria-label="Main navigation">{nav}</nav><div class="header-cta"><a class="button primary small" href="index.html#install">Get CBR {icon('arrow')}</a></div></div></header>
<main id="main">{content}</main>
<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="index.html">{brand}</a><p>A crimson space interface and a clearer place for your Kodi movies, series and live TV.</p></div><div class="footer-links"><h3>Get started</h3><a href="android.html">Android & Fire TV installation</a><a href="windows.html">Windows installation</a><a href="help.html#tv-guide">Set up the channel guide</a><a href="help.html#pairing">Phone / PC source setup</a></div><div class="footer-links"><h3>The project</h3><a href="help.html#updates">Release notes</a><a href="https://github.com/Anakra1/androitdtvfire">Source code on GitHub ↗</a><a href="../">Kodi repository source ↗</a><a href="mailto:crimsonbloodrequiem@gmail.com">crimsonbloodrequiem@gmail.com</a></div></div><div class="footer-bottom"><span>Crimson Blood Requiem · An independent community project for Kodi.</span><span>Windows · Android TV · Fire TV</span></div></div></footer></body></html>'''
    (SITE / filename).write_text(output, encoding='utf-8')


home = f'''
<section class="hero"><img class="hero-art" src="assets/crimson-fleet.jpg" alt="A fleet of dark spacecraft beneath a crimson nebula and a glowing planet" width="1920" height="1080" fetchpriority="high"><div class="wrap hero-content"><div class="hero-copy"><div class="release-tag">CBR <span data-version="android">{versions['android']}</span> · Available now</div><p class="eyebrow kicker">Crimson Blood Requiem for Kodi</p><h1>Your Kodi.<span class="accent">In crimson.</span></h1><p class="lead">Movies, series and live TV in one add-on. Explore your sources, build your channel guide and make Kodi your own with a dark, space-inspired interface.</p><div class="actions"><a class="button primary" href="android.html">{icon('tv')} Android / Fire TV {icon('arrow')}</a><a class="button" href="windows.html">{icon('windows')} Windows {icon('arrow')}</a></div><p class="hero-note">Install through Kodi. Add the optional CBR skin whenever you’re ready.</p></div></div><span class="hero-foot">One add-on. Your own universe.</span></section>
<div class="compat-strip"><div class="wrap compat-inner"><span>{icon('windows')} Windows PC</span><span>{icon('tv')} Android TV & Fire TV</span><span>{icon('guide')} Kodi TV & programme guide</span><span>{icon('source')} Multiple manifest sources</span></div></div>
<section class="section wrap" id="features"><div class="section-heading"><div><p class="eyebrow kicker">What is CBR?</p><h2>A familiar way to watch.<br>A little more yours.</h2></div><p>CBR brings your provider catalogues and playback into Kodi, with separate movie, series and live TV browsing.</p></div><div class="feature-grid"><article class="feature"><span>01 /</span><div><h3>Find your next watch</h3><p>Browse movie and series listings with artwork and dedicated searches. Connect multiple Stremio-compatible manifests from the source manager.</p></div></article><article class="feature"><span>02 /</span><div><h3>Give live TV a proper guide</h3><p>Bring supported channels into Kodi’s TV section, with channel logos, editable groups and programme schedules where available.</p></div></article><article class="feature"><span>03 /</span><div><h3>Put the remote down for setup</h3><p>Pair a phone or PC on your home network to paste manifest links, organise channels and match missing programme listings.</p></div></article><article class="feature"><span>04 /</span><div><h3>Keep playback together</h3><p>The platform-specific packages include Windows playback or install the Android engine through Kodi. No separate companion app to start.</p></div></article></div></section>
<section class="look-section"><div class="wrap section look-grid"><div class="art-panel"><img src="assets/cbr-icon.png" alt="CBR Crimson Blood Requiem add-on artwork featuring the crimson space fleet" width="512" height="512" loading="lazy"><p class="art-caption">Original CBR add-on artwork</p></div><div class="look-copy"><p class="eyebrow kicker">Make it Crimson</p><h2>A darker corner<br>of the universe.</h2><p>Deep blacks. Crimson highlights. A fleet against the stars. The optional CBR skin carries the look through Kodi, including its TV and guide screens.</p><p>Install the add-on first, then use the CBR Setup Wizard to apply the space interface. Your previous skin can be restored from the wizard.</p><a class="text-link" href="help.html#skin">Set up the CBR appearance {icon('arrow')}</a></div></div></section>
<section class="section wrap" id="install"><div class="section-heading"><div><p class="eyebrow kicker">Choose your platform</p><h2>Get CBR on your screen.</h2></div><p>Start with Kodi 21 or newer. Choose your device below for the correct repository and step-by-step installation.</p></div><div class="downloads"><article class="download-card"><div class="card-top"><div class="device-icon">{icon('tv')}</div><span class="card-label">Android · Fire TV</span></div><h3>The living-room setup.</h3><p>For Firesticks, Fire TV televisions and Android TV boxes running Kodi. Kodi installs the CBR Playback Engine with the add-on.</p><a class="button primary" href="android.html">Android / Fire TV guide {icon('arrow')}</a></article><article class="download-card"><div class="card-top"><div class="device-icon">{icon('windows')}</div><span class="card-label">Windows · 64-bit</span></div><h3>A home on your PC.</h3><p>A dedicated Windows repository and a bundled Windows playback engine, with the same CBR catalogues, tools and optional skin.</p><a class="button" href="windows.html">Windows installation guide {icon('arrow')}</a></article></div>{source_panel()}</section>
<section class="wrap help-banner"><div><h3>A little help getting settled?</h3><p>Find pairing instructions, channel-guide setup and answers to common questions.</p></div><a class="button" href="help.html">Help & updates {icon('arrow')}</a></section>'''
render('index.html', 'CBR for Kodi — Windows, Android & Fire TV', 'Meet Crimson Blood Requiem: movie, series and live TV browsing for Kodi, with a crimson space skin and separate Windows and Android install guides.', home)


def install_page(platform):
    android = platform == 'android'
    label = 'Android / Fire TV' if android else 'Windows'
    filename = 'repository.cbr.zip' if android else 'windowsrepo.zip'
    repository = 'CBR Android Add-on Repository' if android else 'CBR Windows Add-on Repository'
    update = 'cbr' + versions['android'].replace('.', '') + '.zip' if android else 'cbrwindows.zip'
    update_attr = ' data-android-update' if android else ''
    update_name = f'<span data-update-name>{update}</span>' if android else update
    detail = 'Firesticks, Fire TV televisions and Android TV boxes' if android else '64-bit Windows PCs'
    engine_note = 'Accept the dependency list, including <strong>CBR Playback Engine</strong>. Kodi installs it automatically. There is no separate companion APK to install.' if android else 'The Windows playback engine is already bundled. The Windows package does not require the Android CBR Playback Engine module.'
    hero = page_hero(label, 'CBR on your<br><span class="accent">' + ('big screen.' if android else 'Windows PC.') + '</span>',
                     f'Install Crimson Blood Requiem on {detail} through Kodi’s repository system.',
                     f'<div class="pill-row"><span class="pill">Kodi 21+</span><span class="pill">Video add-on <span data-version="{platform}">{versions[platform]}</span></span><span class="pill">Optional skin & wizard</span></div>')
    return hero + f'''<section class="section wrap guide-layout"><div class="guide-body"><p class="eyebrow kicker">First-time installation</p><h2>One source. A few clear steps.</h2><p>These steps start inside Kodi. If Kodi is not installed yet, get it from the <a class="text-link" href="https://kodi.tv/download/">official Kodi download page ↗</a>.</p>{source_panel('install-source')}
    <ol class="step-list"><li><h3>Add CBR as a file source</h3><p>Open Kodi’s settings and follow:</p><span class="path">File manager → Add source → &lt;None&gt;</span><p>Enter the source address above exactly, including <strong>https://</strong>. Name the source <strong>CBR</strong> and select OK.</p></li>
    <li><h3>Install the {label} repository</h3><span class="path">Add-ons → Install from zip file → CBR → <strong>{filename}</strong></span><p>If Kodi asks you to enable Unknown sources, use <strong>Settings → System → Add-ons → Unknown sources</strong>, then return to this step.</p></li>
    <li><h3>Install Crimson Blood Requiem</h3><span class="path">Install from repository → {repository} → Video add-ons → Crimson Blood Requiem → Install</span><p>{engine_note}</p></li>
    <li><h3>Restart Kodi, then open CBR</h3><p>Fully close and reopen Kodi to load the background services. Open <strong>Add-ons → Video add-ons → Crimson Blood Requiem</strong>, using the crimson CBR thumbnail.</p><p>Choose your movie, series or live TV section. Provider links and schedules depend on the sources configured on this device.</p></li></ol>
    <div class="subsection" id="updating"><p class="eyebrow">Already installed?</p><h2>Update without starting over.</h2><p>Use the video add-on’s <strong>Information → Update</strong> option. If Kodi’s repository list has not refreshed, install the latest platform ZIP directly:</p><span class="path">Install from zip file → CBR → <strong>{update}</strong></span><p>Restart Kodi afterwards. You do not need to uninstall CBR or reinstall the skin for a video add-on update.</p><a class="text-link" href="../{update}"{update_attr} download>{icon('download')} Download {update_name}</a></div>
    <div class="subsection"><h2>Next: channels, sources and the skin.</h2><p>For the native TV guide, source pairing or the optional crimson interface, follow the setup instructions on the help page.</p><a class="text-link" href="help.html">Continue to CBR help {icon('arrow')}</a></div></div>
    <aside class="guide-aside" aria-label="{label} installation downloads"><div class="device-icon">{icon('tv' if android else 'windows')}</div><p class="eyebrow" style="margin-top:22px">{label} downloads</p><h3>Use the right repository.</h3><p>For a first install, choose <strong>{filename}</strong> in Kodi’s CBR source.</p><a class="button primary" href="../{filename}" download>{icon('download')} Download repository ZIP</a><a class="button" href="../{update}"{update_attr} download>Latest video add-on ZIP {icon('arrow')}</a><div class="aside-note"><p><strong>Installing with a TV remote?</strong><br>Add the short source address in Kodi. You can select the ZIP there without typing a download filename.</p></div><div class="aside-note"><p>Using {'a Windows PC' if android else 'Android or Fire TV'} instead?</p><a class="text-link" href="{'windows' if android else 'android'}.html">Open that install guide {icon('arrow')}</a></div></aside></section>'''


render('android.html', 'Android & Fire TV installation', 'Install or update Crimson Blood Requiem on Firestick, Fire TV and Android TV through the CBR Kodi repository.', install_page('android'))
render('windows.html', 'Windows installation', 'Install Crimson Blood Requiem through the dedicated Windows Kodi repository, with the Windows playback engine included.', install_page('windows'))

help_content = page_hero('Help & updates', 'A smoother setup.<br><span class="accent">A better evening.</span>', 'Set up your sources, organise the TV guide and make CBR feel at home on your screen.') + f'''
<div class="wrap jump-links" aria-label="Help topics"><a href="#pairing">Phone / PC pairing</a><a href="#tv-guide">TV & channel guide</a><a href="#skin">CBR skin</a><a href="#questions">Troubleshooting</a><a href="#updates">Release notes</a></div>
<section class="section wrap"><div class="help-grid"><article class="help-topic" id="pairing"><p class="eyebrow">Sources without remote typing</p><h2>Pair a phone or PC.</h2><ol><li>In CBR, open <strong>Source setup (phone / PC)</strong>. Keep the Kodi pairing screen open.</li><li>Connect your phone or PC to the same home network as the Kodi device.</li><li>Enter the exact <strong>http://</strong> address shown by Kodi into your browser’s address bar, including its port number. Enter the six-digit pairing code.</li><li>Choose <strong>Edit</strong> beside a source, paste its full configured manifest URL, and save. You can also add other providers.</li></ol><p>The pairing page runs on your Kodi device and is available for up to ten minutes. It is separate from this public website.</p></article>
<article class="help-topic" id="tv-guide"><p class="eyebrow">Kodi’s native TV section</p><h2>Build your channel guide.</h2><ol><li>Open <strong>CBR → Live TV → Kodi TV and guide → Set up Kodi TV / IPTV Simple Client</strong>.</li><li>Allow Kodi to install its official <strong>PVR IPTV Simple Client</strong> if needed. Let the channel build finish.</li><li>Open Kodi’s main <strong>TV → Channels</strong> or <strong>TV → Guide</strong>, then choose the CBR TV, Freeview, Sky or other groups.</li><li>In the paired PC page, use <strong>Kodi TV and guide</strong> to edit names, numbers and groups, hide channels or match missing programmes.</li></ol><p>Group names and starter numbers are editable. They are not an exact regional provider lineup. Guide coverage depends on matching schedule data.</p></article>
<article class="help-topic" id="skin"><p class="eyebrow">The optional crimson interface</p><h2>Make the whole screen CBR.</h2><ol><li>Install <strong>Crimson Blood Requiem Skin</strong> and <strong>CBR Setup Wizard</strong> from the CBR repository. The wizard is under Program add-ons.</li><li>Open the wizard and choose <strong>Apply CBR space interface</strong>.</li><li>To go back later, open the wizard and select <strong>Restore previous Kodi interface</strong>.</li></ol><p>The video add-on works with Kodi’s normal skin too. Changing the skin keeps your existing provider settings in place.</p></article>
<article class="help-topic"><p class="eyebrow">Keep things current</p><h2>Manifests and schedules.</h2><p>A manifest tells CBR which catalogues or sources a provider offers. Some providers need a personal configured link, and that link may expire.</p><p>Use the complete link generated by the provider, including its configuration path or ID. A public default URL may not contain your channel choices.</p><p>Programme schedules are separate XMLTV feeds. The UK schedule feed is included; other countries may need their own feed added through the paired setup page.</p><a class="text-link" href="#questions">Troubleshooting {icon('arrow')}</a></article></div>
<section class="subsection" id="questions"><p class="eyebrow kicker">Troubleshooting</p><h2>A few common questions.</h2><div class="faq-list">
<details><summary>Kodi says a dependency failed to install. What now?</summary><div><p>Check that you used the repository for your device. On Windows, install <strong>windowsrepo.zip</strong>, then choose <strong>CBR Windows Add-on Repository</strong>. Windows version 0.9.2 removes the unnecessary Android engine dependency.</p><p>On Android/Fire TV, use <strong>repository.cbr.zip</strong> and accept the CBR Playback Engine dependency. For a first install, use the repository route so Kodi can find dependencies.</p></div></details>
<details><summary>“Could not retrieve directory information” appears in Kodi.</summary><div><p>Check that the source is exactly <strong>{SOURCE}</strong>. Include <strong>https://</strong> and check the spelling of <strong>androitdtvfire</strong>. Use the repository source address, not this website’s /website/ address or a GitHub project page.</p><p>Check the device’s internet connection, then reopen the source.</p></div></details>
<details><summary>The phone or PC searches Google instead of opening the pairing page.</summary><div><p>Use the browser’s address bar and enter the full address shown in Kodi, starting with <strong>http://</strong>. Keep the colon and port number. Do not change it to https://.</p><p>Both devices must be on the same home network. Keep the pairing screen open in Kodi. Guest Wi-Fi isolation or a VPN blocking local access can prevent the connection.</p></div></details>
<details><summary>A sports or TV provider asks for a new manifest.</summary><div><p>Generate a fresh configured manifest using that provider’s setup page. Open CBR’s paired phone/PC source manager, edit the existing provider, replace its full URL and save.</p><p>A provider’s plain default manifest may still return a setup notice. Keep personal configured links in your device settings rather than sharing them publicly.</p></div></details>
<details><summary>A channel plays but has no programme information.</summary><div><p>Playback and schedules come from different sources. In the paired setup page, filter channels by <strong>Missing programme listings</strong>. Expand <strong>Choose programme guide match</strong>, select the correct schedule and use <strong>Apply programme match</strong>.</p><p>Regional and +1 channels are kept distinct. Some channels have no available schedule. Restart Kodi to apply guide changes sooner than the normal PVR refresh.</p></div></details>
<details><summary>One channel fails while others work.</summary><div><p>The selected provider stream may be temporarily unavailable. Try again later, or check the channel in CBR’s backup Live TV browser, where the long-press menu includes a manual source chooser.</p><p>HTTP availability checks can skip blocked links, but cannot guarantee a stream decodes correctly or detect every picture loop.</p></div></details>
<details><summary>The skin is still Kodi’s normal interface.</summary><div><p>The video add-on and skin are separate installations. Install the CBR skin and setup wizard from your platform repository, then run the wizard and choose <strong>Apply CBR space interface</strong>.</p></div></details>
<details><summary>Do my personal manifests move to a second device?</summary><div><p>No. Each device keeps its own configured sources. Use its paired phone/PC setup page to add your links. Some providers may need a fresh configuration or verification for a different connection.</p></div></details>
</div></section>
<section class="subsection" id="updates"><p class="eyebrow kicker">Release notes</p><h2>The latest from CBR.</h2><div class="release-row"><div class="release-number">0.9.2</div><div><h3>Correct platform packages</h3><p>Windows uses its bundled engine without the Android module dependency. Windows and Android package metadata now identify their platforms. Working Android 0.9.1 installations already include the channel and guide improvements.</p></div></div><div class="release-row"><div class="release-number">0.9.1</div><div><h3>A cleaner lineup, more programme matches</h3><p>Spacing-only duplicates combine while preserving alternative links and existing numbers. Added known UK guide-name aliases, PC editor filters, pagination, bulk hide/show and manual guide matching.</p></div></div><div class="release-row"><div class="release-number">0.9.0</div><div><h3>CBR meets Kodi TV</h3><p>Introduced local M3U and XMLTV output for PVR IPTV Simple Client, bringing supported channels and programme schedules into Kodi’s TV and Guide sections.</p></div></div></section>
<div class="contact-box"><p class="eyebrow">Get in touch</p><h3>Tell us what you’re seeing.</h3><p>Include your device model, Kodi version, CBR version and the exact error message. Keep passwords and personal configured manifest URLs out of your message.</p><a class="text-link" href="mailto:crimsonbloodrequiem@gmail.com?subject=CBR%20support">crimsonbloodrequiem@gmail.com {icon('arrow')}</a></div>
<p class="source-note" style="margin-top:25px">This website has no account signup or analytics scripts. CBR’s paired source manager runs locally on your Kodi device.</p></section>'''
render('help.html', 'Help, setup & release notes', 'CBR help for phone/PC pairing, manifest updates, channel guides, the crimson skin, installation errors and release notes.', help_content)
print('Built four CBR website pages. Kodi source index unchanged.')
